import { useEffect, useState } from "react";
import MenuCard from "./MenuCard";

export default function MenuGrid({ addToCart }) {
  const [menu, setMenu] = useState([]);

  useEffect(() => {
    fetch("http://127.0.0.1:8000/menu/")
      .then(res => res.json())
      .then(setMenu);
  }, []);

  return (
    <div className="menu-grid">
      {menu.map(item => (
        <MenuCard
          key={item.id}
          item={item}
          addToCart={addToCart}
        />
      ))}
    </div>
  );
}
